p as (select x.id, s.* from parcels x join src s on s.prop_id = x.epcad_property_id, org where x.org_id = org.id),
del as (delete from tax_bills t using p where t.parcel_id = p.id and t.entity like 'El Paso Tax Office%' returning t.id),
ins as (
  insert into tax_bills (org_id, parcel_id, entity, tax_year, amount_due, delinquent)
  select (select id from org), p.id, 'El Paso Tax Office (all entities), 2026 bill', 2026, p.cur, false from p where p.cur > 0
  union all
  select (select id from org), p.id, 'El Paso Tax Office (all entities), prior years', 2025, p.prior, true from p where p.prior > 0
  returning id
),
upd as (
  update parcels x set
    notes = concat_ws(E'\n', nullif(regexp_replace(coalesce(x.notes, ''), E'\n?Taxes \\(El Paso Tax Office[^\n]*', '', 'g'), ''), p.note),
    tags = case when p.prior > 0 then (select array(select distinct unnest(x.tags || array['tax_delinquent']::text[]))) else x.tags end,
    updated_at = now()
  from p where x.id = p.id
  returning x.id
)
select (select count(*) from p) as properties, (select count(*) from ins) as tax_rows, (select count(*) from upd) as updated;
